/* From Uiverse.io by Alanav29  - Tags: simple, email, minimalist, input, light, toggle, text animation, input effect  */
.__UIV_SCOPE__ .input-container {
  width: auto;
  position: static;
  display: flex;
  flex-direction: column-reverse;
}

.__UIV_SCOPE__ .input-container label {
  color: black;
  position: relative;
  top: 2px;
  border: solid white;
  border-top: none;
  border-right: none;
  border-left: none;
  width: fit-content;
  transition: transform 0.2s;
  margin: 0px 0px 0px 12px;
  padding: 0px 4px 0px 4px;
  font-size: 20px;
}

.__UIV_SCOPE__ .input-container input:focus + label {
  color: rgb(161, 66, 249);
  transform: scale(1.2);
  transform: translateX(0.5rem);
}

.__UIV_SCOPE__ .input-container input {
  border: 2px rgb(161, 66, 249) solid;
  padding: 8px;
}

.__UIV_SCOPE__ .input-container input:focus {
  outline: none;
}
